-- Reviewed notice anchors inside hash-pinned notice files. A range spans whole lines from the
-- start anchor line to the end anchor line; text_sha256 pins the reviewed bytes.
-- style: comment (must pass the comment-only check), license-document (whole file),
-- document-section (one section of a license document, not source code).
CREATE TABLE notice_range_rule (project TEXT NOT NULL, version TEXT NOT NULL, notice_path TEXT NOT NULL, notice_sha256 TEXT NOT NULL, style TEXT NOT NULL CHECK (style IN ('comment','license-document','document-section')), start_marker TEXT NOT NULL, end_marker TEXT NOT NULL, text_sha256 TEXT NOT NULL, PRIMARY KEY (project, version, notice_path));
